fn main(){ let t=alw_core::textures::build_textures(16); let n=16*16; for name in ["grass","dirt","sand","stone","water","oak_leaves","snow","planks","thatch","path","spruce_leaves","cobblestone"] { let Some(id)=alw_core::blocks::by_name(name) else {continue}; let b=&alw_core::blocks::BLOCKS[id as usize]; let l=b.faces[0] as usize; let px=&t.albedo[l*n*4..(l+1)*n*4]; let mut c=[0u32;3]; for p in px.chunks(4){for k in 0..3{c[k]+=p[k] as u32;}} println!("{name} {:?} tint {:?}", c.map(|v|v/n as u32), b.tint); } }
